use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let arr = input.as_array().unwrap();
    let a = arr[0].as_str().unwrap().to_ascii_lowercase().chars().filter(|c| !c.is_ascii_whitespace()).collect::<String>();
    let b = arr[1].as_str().unwrap().to_ascii_lowercase().chars().filter(|c| !c.is_ascii_whitespace()).collect::<String>();
    let mut count_a = [0; 256];
    let mut count_b = [0; 256];
    for c in a.chars() {
        count_a[c as usize] += 1;
    }
    for c in b.chars() {
        count_b[c as usize] += 1;
    }
    count_a == count_b
}
